// credence-transportcheck evaluates one snapshot over both transports and
// compares the bytes.
//
// `docs/10` accepts the isolated gRPC change "only if it passes identical
// canonicalization vectors and the applicable acceptance matrix without
// changing those frozen artifacts". This is the sharpest form of that
// test: if HTTP and gRPC return assessments that differ by a single byte,
// the transport changed a decision, and a retained assessment would stop
// reproducing under the other one.
//
// Neither side is a mock. The server is tonic, the client is generated by
// protoc-gen-go-grpc, and both come from `schemas/proto/risk.proto`.
package main

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"time"

	"github.com/arcbjorn/credence/gateway/riskclient"
)

func main() {
	httpURL := flag.String("http", "http://127.0.0.1:18131", "HTTP base URL")
	grpcAddr := flag.String("grpc", "127.0.0.1:18132", "gRPC target")
	inputPath := flag.String("input", "", "a retained snapshot")
	policyPath := flag.String("policy", "", "the policy it was assessed under")
	flag.Parse()

	if *inputPath == "" || *policyPath == "" {
		fail("-input and -policy are required")
	}

	input, err := os.ReadFile(*inputPath)
	if err != nil {
		fail("read input: %v", err)
	}
	policy, err := os.ReadFile(*policyPath)
	if err != nil {
		fail("read policy: %v", err)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
	defer cancel()

	httpClient := riskclient.New(*httpURL, 30*time.Second)
	grpcClient, err := riskclient.NewGRPC(*grpcAddr, 30*time.Second)
	if err != nil {
		fail("dial grpc: %v", err)
	}
	defer grpcClient.Close()

	// Both must be up. A skipped transport that reported success would
	// make this check worthless.
	if err := httpClient.Health(ctx); err != nil {
		fail("http health: %v", err)
	}
	if err := grpcClient.Health(ctx); err != nil {
		fail("grpc health: %v", err)
	}

	// The engine each transport reaches must be the same one, or equal
	// output would prove nothing about the transport.
	modelHash, err := grpcClient.ModelHash(ctx)
	if err != nil {
		fail("model hash: %v", err)
	}
	fmt.Printf("  engine     %s\n", modelHash)

	overHTTP, err := httpClient.Assess(ctx, input, policy)
	if err != nil {
		fail("assess over http: %v", err)
	}
	overGRPC, err := grpcClient.Assess(ctx, input, policy)
	if err != nil {
		fail("assess over grpc: %v", err)
	}

	sumHTTP := sha256.Sum256(overHTTP)
	sumGRPC := sha256.Sum256(overGRPC)
	fmt.Printf("  http       %d bytes, sha256 %s\n", len(overHTTP), hex.EncodeToString(sumHTTP[:])[:16])
	fmt.Printf("  grpc       %d bytes, sha256 %s\n", len(overGRPC), hex.EncodeToString(sumGRPC[:])[:16])

	if !bytes.Equal(overHTTP, overGRPC) {
		// Show WHERE, not just that they differ: a reader fixing this
		// needs the field, and a diff of two 8KB blobs is unreadable.
		fail("the two transports disagree\n%s", firstDifference(overHTTP, overGRPC))
	}

	// The assessment must also be usable, not merely identical: two
	// transports could agree on the same garbage.
	var assessment map[string]json.RawMessage
	if err := json.Unmarshal(overHTTP, &assessment); err != nil {
		fail("the assessment is not valid JSON: %v", err)
	}
	if _, ok := assessment["input_hash"]; !ok {
		fail("the assessment carries no input_hash")
	}

	// Replay, over both, on the assessment gRPC just produced.
	replayHTTP, err := httpClient.Replay(ctx, overHTTP, input, policy)
	if err != nil {
		fail("replay over http: %v", err)
	}
	replayGRPC, err := grpcClient.Replay(ctx, overGRPC, input, policy)
	if err != nil {
		fail("replay over grpc: %v", err)
	}
	if replayHTTP.Matched != replayGRPC.Matched {
		fail("replay verdicts differ: http=%v grpc=%v", replayHTTP.Matched, replayGRPC.Matched)
	}
	if !replayHTTP.Matched {
		fail("the assessment did not replay against its own input")
	}
	fmt.Printf("  replay     MATCH on both, input_hash %s\n", replayHTTP.InputHash[:16])

	fmt.Println()
	fmt.Println("PASS  gRPC and HTTP produce byte-identical assessments")
	fmt.Println()
	fmt.Println("  Same snapshot, same policy, same engine, two wire formats.")
	fmt.Println("  A single byte of difference would mean the transport")
	fmt.Println("  changed a decision, and retained evidence would stop")
	fmt.Println("  reproducing under the other one.")
}

// firstDifference names where two payloads diverge.
func firstDifference(a, b []byte) string {
	limit := len(a)
	if len(b) < limit {
		limit = len(b)
	}
	for i := 0; i < limit; i++ {
		if a[i] != b[i] {
			from := i - 40
			if from < 0 {
				from = 0
			}
			to := i + 40
			if to > limit {
				to = limit
			}
			return fmt.Sprintf("  first differs at byte %d\n  http: %q\n  grpc: %q",
				i, a[from:to], b[from:to])
		}
	}
	return fmt.Sprintf("  identical for %d bytes, then lengths differ: http=%d grpc=%d",
		limit, len(a), len(b))
}

func fail(format string, args ...any) {
	fmt.Fprintf(os.Stderr, "FAIL  "+format+"\n", args...)
	os.Exit(1)
}
